// Generate src/api/schema.gen.ts from src/api/openapi.json (exported from the backend by
// tools/export_contract.py). `--check` writes nothing and fails if the committed file is stale.
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import openapiTS, { astToString } from "openapi-typescript";

const src = new URL("../src/api/openapi.json", import.meta.url);
const out = new URL("../src/api/schema.gen.ts", import.meta.url);
const header =
  "// SPDX-License-Identifier: AGPL-3.0-only\n" +
  "// GENERATED by `npm run gen:api` from src/api/openapi.json. Do not edit by hand.\n\n";

const ast = await openapiTS(JSON.parse(readFileSync(src, "utf8")));
const text = header + astToString(ast);

if (process.argv.includes("--check")) {
  const current = existsSync(out) ? readFileSync(out, "utf8") : "";
  if (current !== text) {
    console.error("src/api/schema.gen.ts is out of date: run `npm run gen:api` and commit it.");
    process.exit(1);
  }
  console.log("schema.gen.ts is up to date");
} else {
  writeFileSync(out, text);
  console.log("wrote src/api/schema.gen.ts");
}
